"""Cover art: one object per post, generated by the Codex CLI's built-in image tool (the owner's ChatGPT plan, no API key).

Runs on the owner's machine during review, not in the cloud: the generated PNG is saved to assets/art/<name>.png and
committed, and the post's cover points at it by name (draft.cover.art)."""
from __future__ import annotations

import subprocess

from . import config

STYLE = ("flat vector editorial illustration, warm and clean, soft shadows, one clear scene an Indian reader recognises in a "
         "second, no people's faces, no readable text, no logos or brand marks, transparent background, landscape 4:3")


def generate(name: str, brief: str, timeout: int = 600) -> str:
    """Generate assets/art/<name>.png from a one-line brief; returns the art name the cover uses."""
    out = config.ASSETS / "art" / f"{name}.png"
    ask = (f"Use your built-in image_gen tool (not the CLI) to generate one image: {brief}. Style: {STYLE}. "
           f"Then copy the generated PNG to assets/art/{name}.png in this workspace, overwriting it, and reply with just the path.")
    subprocess.run(["codex", "exec", "--skip-git-repo-check", "--sandbox", "workspace-write", "-C", str(config.ROOT), ask],
                   check=True, timeout=timeout, capture_output=True, text=True)
    if not out.exists():
        raise RuntimeError(f"Codex finished but {out} was not written")
    return name
